"""Report the fixed primary alongside every frozen, direct, raw and mismatched control."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[2];H=R/'research/round97';S=H/'scores_attempt001';rd=lambda p:json.loads(p.read_text())
def main():
 assert rd(H/'SCALAR_AUDIT.json')['state'].startswith('PASS_');rows=rd(S/'ALL_METHOD_ROWS.json');agg=rd(S/'AGGREGATE_ROWS.json');paired=rd(S/'ALL_PAIRED_ROWS.json');cost={};lines=['# R97 — 固定R91方法的三个source、六方向TTA','','本轮固定用户选定的R91 R76_full_disc双向结构及原物理恢复一步回溯physical_bt。未采用已停止的R95 LM，不新增损失、视觉专家、更新层或目标域搜索；原始source100参数与每输入的A256框固定。每输入恢复其source准备状态。FINAL帧在清单生成前排除。','', '## 六方向固定主结果','', '| source→target | n | 原始source | 准备后零步 | 同信息概率均值 | 同信息表示均值 | 固定TTA | TTA−零步 pp | TTA−概率均值 pp |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for src in ['waymo','drone','quad']:
  for tgt in ['waymo','drone','quad']:
   if src==tgt:continue
   ss={r['arm']:r for r in rows if r['source']==src and r['target']==tgt};v=lambda a:ss[a]['mIoU_percent'];lines.append(f"| {src}→{tgt} | {ss['physical_bt']['n']} | {v('original_source'):.6f} | {v('prepared_frozen'):.6f} | {v('direct_mean3'):.6f} | {v('direct_feature3'):.6f} | {v('physical_bt'):.6f} | {v('physical_bt')-v('prepared_frozen'):+.6f} | {v('physical_bt')-v('direct_mean3'):+.6f} |")
   cost[src+'_to_'+tgt]=rd(R/'crossplatform/round97'/(src+'_to_'+tgt)/'SEALED.json')
 lines+=['','## 等权汇总与目标平台','','六方向各占1/6；各目标平台由两个入向source等权平均。另保留所有逐方向、逐场景和逐例值，不用样本量较大的Waymo掩盖其他平台。','', '| 范围 | 方法 | mIoU % | Acc25 % | Acc50 % |','|---|---|---:|---:|---:|']
 for a in agg:lines.append(f"| {a['target_group']} | {a['arm']} | {a['mIoU_percent']:.6f} | {a['Acc25_percent']:.6f} | {a['Acc50_percent']:.6f} |")
 lines+=['','## 改善、损伤与全部负比较','','| 方向 | 对照 | ΔmIoU pp | 改善/恶化/不变 | Acc25救回/破坏 |','|---|---|---:|---:|---:|']
 for p in paired:lines.append(f"| {p['source']}→{p['target']} | {p['control']} | {p['gain_pp']:+.6f} | {p['better']}/{p['worse']}/{p['same']} | {p['Acc25_rescue']}/{p['Acc25_break']} |")
 lines+=['','## 固定方法与source准备','','三个原始模型沿用R96的Waymo-only/Drone-only/Quad-only epoch100。Waymo配套模块复用已有R76/R91参数；Drone/Quad不能加载Waymo准备权重，各自只用source TRAIN512/VAL128按同一结构和损失准备：双向融合8epoch，AdamW3e-4；冻结融合后full_disc接口4epoch，AdamW1e-4。均clip1、weight_decay1e-4，sourceVAL最早最大值选择；无target选择。只迁移当前full_disc分支，未重跑原R91十个消融分支的联合epoch选择，故新增source的选epoch统计口径是单分支sourceVAL。本差异在目标评分前注册。','', '源附加物体7D框和主体9D框并存，依官方box_util的xyz/lwh/yaw[,pitch,roll]定义补齐缺失角度后做原native变换；没有改变目标评价几何。全部source额外物体标签仅服务source竞争训练，不进入TTA。源与目标在不同方向中的身份按各模型独立定义，不能把另一方向的source标签当当前方向测试监督。','']
 for src in ['drone','quad']:
  c=rd(R/'crossplatform/round97'/src/'SOURCE_COMPLETE.json');audit=next(x for x in rd(H/'SOURCE_PREPARATION_AUDIT.json')['rows'] if x['source']==src);lines.append(f"- {src}: fusion epoch{c['fusion_selected']['epoch']}, head epoch{c['head_selected']['epoch']}, {c['updates']}次训练尝试，{audit['actual_optimizer_updates']}次有效优化器更新，耗时{c['seconds']:.3f}s；原始100epoch模型未变，无角色信号的尝试保留。")
 lines+=['', 'TTA保持原102498参数范围；完整输入及两固定互补遮挡76001/76002共用点云、RGB、标定和文字。物理loss为0.1点表征＋0.1RGB＋0.01图像单支深度；SGD clip1、初始0.5，Armijo1e-4/tol1e-10，最多9个二分幅度。判别接口参与实际读出和保持验收，但首步物理梯度仍沿原R91接口关闭路径；本轮不修此已知限制。错配绑定raw/BT与无回溯raw完整保留，不在看到目标GT后升级为主方法。','', '概率均值和表示均值使用同一完整输入和相同两遮挡，不更新参数；与TTA具有相同观测，避免仅以裸source宣称适应价值。UNKNOWN、无可见支持、无有效更新、回退和所有零IoU样本均在总分分母内。','', '## 采样、审计与适用范围','','使用表达式级固定点采样，所有实验臂共用；R96用官方batch采样，因而其原表仅作为同清单历史参照。本轮原始source在匹配输入上重算，不把采样变化混入TTA增量。RGB物理缓存只在seed/sample哈希完全一致时复用，当前source自己的query anchor indices重新绑定；抽查原始媒体重放不使用该缓存。','', '原R91已存Drone/Quad案例的7个准备后读出由新执行入口重放：概率最大误差0，Top1完全一致。正式全部六方向预测封存并完成原生抽查后才评分；主选框IoU另用通用3D凸体交核对，完整标量由独立汇总程序复核。','', 'Drone仅2个验证场景，Quad仅3个，Waymo93个；18,620个有向任务输入不是18,620个独立场景。来源于已暴露验证范围，不宣称新独立测试或总体显著性。未查看FINAL输入/评分；未进行按平台选步幅、按负例删样本或后验切换方法。','', '## 成本','','| 方向 | 完整执行秒 | GPU峰值bytes |','|---|---:|---:|']
 for name,c in cost.items():lines.append(f"| {name} | {c['seconds']:.3f} | {c['peak_GPU_bytes']} |")
 aa={a['arm']:a for a in agg if a['target_group']=='all_six_equal'};v=lambda a:aa[a]['mIoU_percent'];win=all(v('physical_bt')>v(a) for a in ['prepared_frozen','direct_mean3','direct_feature3']);dec={'method':'R91_R76_full_disc_physical_bt','primary_mean_mIoU_percent':v('physical_bt'),'gain_vs_own_frozen_pp':v('physical_bt')-v('prepared_frozen'),'gain_vs_same_info_probability_pp':v('physical_bt')-v('direct_mean3'),'gain_vs_same_info_feature_pp':v('physical_bt')-v('direct_feature3'),'above_three_main_controls_in_equal_six_mean':win,'independent_confirmation':False,'target_tuning':False,'FINAL_access':False,'negative_directions_retained':True,'not_promote_secondary_raw_or_wrong_control':True};(H/'DECISION.json').write_text(json.dumps(dec,indent=2)+'\n');lines+=['','## 固定配方裁决','',f"固定主方法相对自身零步{dec['gain_vs_own_frozen_pp']:+.6f}pp，相对同信息概率均值{dec['gain_vs_same_info_probability_pp']:+.6f}pp，相对同信息表示均值{dec['gain_vs_same_info_feature_pp']:+.6f}pp。等权六方向同时超过三项主要对照={win}。该判断只涉及本固定配方和已有范围；不按控制组或单域最佳结果替换主配方，也不把辅助loss下降当grounding增益。",''];(H/'REPORT.md').write_text('\n'.join(lines));print(dec)
if __name__=='__main__':main()
